{
  "findings": [
    {
      "check_id": "CKV_AZURE_26",
      "title": "Ensure that 'Send Alerts To' is enabled for MSSQL servers",
      "resource": "azurerm_mssql_server_security_alert_policy.recovery_db_alerts",
      "severity": "MEDIUM",
      "explanation": "The 'email_addresses' field is not configured, meaning no recipients are set to receive security alerts. This could result in missed notifications for critical security events."
    },
    {
      "check_id": "CKV_AZURE_27",
      "title": "Ensure that 'Email service and co-administrators' is 'Enabled' for MSSQL servers",
      "resource": "azurerm_mssql_server_security_alert_policy.recovery_db_alerts",
      "severity": "MEDIUM",
      "explanation": "The 'email_account_admins' field is not explicitly set to 'true', which means service and co-administrators may not receive security alerts. This could lead to a lack of visibility into security incidents."
    },
    {
      "check_id": "CKV_AZURE_25",
      "title": "Ensure that 'Threat Detection types' is set to 'All'",
      "resource": "azurerm_mssql_server_security_alert_policy.recovery_db_alerts",
      "severity": "MEDIUM",
      "explanation": "The 'disabled_alerts' field disables specific threat detection types ('Sql_Injection' and 'Data_Exfiltration'), which reduces the effectiveness of security monitoring."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_server_security_alert_policy\" \"recovery_db_alerts\" {\n  resource_group_name        = azurerm_resource_group.dr_platform.name\n  server_name                = azurerm_mssql_server.recovery_sql_server.name\n  state                      = \"Enabled\"\n  storage_endpoint           = azurerm_storage_account.backup_storage.primary_blob_endpoint\n  storage_account_access_key = azurerm_storage_account.backup_storage.primary_access_key\n\n  email_addresses = [\"security-team@example.com\"]\n  email_account_admins = true\n\n  retention_days = 20\n}\n",
  "fix_summary": "Added 'email_addresses' to specify recipients for security alerts, set 'email_account_admins' to true to notify service and co-administrators, and removed 'disabled_alerts' to enable all threat detection types."
}
